(()=>{'use strict';const config=window.SIROKKO_CONFIG||{},goal=(n,p)=>window.SirokkoAnalytics?.goal(n,p),modal=document.createElement('dialog');modal.className='quick-lead-dialog';modal.setAttribute('aria-labelledby','quick-lead-title');modal.innerHTML='<button type="button" class="quick-lead-close" aria-label="Закрыть форму">×</button><div class="eyebrow">SIROKKO / БЫСТРАЯ ЗАЯВКА</div><h2 id="quick-lead-title">Оставьте контакт.<br>Остальное уточним.</h2><p class="quick-lead-caption">Никаких регистраций. Свяжемся с вами и поможем с расчётом.</p><div class="quick-lead-context" id="quick-lead-context"></div><form id="quick-lead-form"><label for="quick-contact">Телефон или Telegram<input id="quick-contact" name="contact" class="ym-disable-keys" type="text" autocomplete="tel" maxlength="100" placeholder="+7 999 123-45-67 или @username" required></label><details class="lead-optional"><summary>Добавить комментарий <span>необязательно</span></summary><textarea name="details" class="ym-disable-keys" rows="3" maxlength="2000" placeholder="Ваш вопрос или ссылка на товар"></textarea></details><label class="lead-consent"><input type="checkbox" name="consent" required><span>Даю <a href="consent.html" target="_blank" rel="noopener">согласие на обработку персональных данных</a>. <a href="privacy.html" target="_blank" rel="noopener">Политика</a></span></label><div class="lead-trap" aria-hidden="true"><label>Ваш сайт<input name="website" tabindex="-1" autocomplete="off"></label></div><button class="btn primary" type="submit">Оставить заявку <span>↗</span></button><div class="lead-status ym-hide-content" role="status" aria-live="polite"></div><div class="lead-alt">Или напишите сами: <a class="lead-tg" target="_blank" rel="noopener">Telegram ↗</a><a class="lead-max" target="_blank" rel="noopener">MAX ↗</a></div></form>';document.body.append(modal);if(config.telegram)modal.querySelector('.lead-tg').href=config.telegram;else modal.querySelector('.lead-tg').hidden=true;if(config.max)modal.querySelector('.lead-max').href=config.max;else modal.querySelector('.lead-max').hidden=true;if(!config.telegram&&!config.max)modal.querySelector('.lead-alt').hidden=true;let modalData={service:'Консультация',source:'quick_form',context:''},previousFocus=null;const uuid=()=>window.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)});function validContact(v){return /^@?[A-Za-z][A-Za-z0-9_]{4,31}$/.test(v)||/^\+?[0-9 ()-]{10,25}$/.test(v)&&v.replace(/\D/g,'').length>=10&&v.replace(/\D/g,'').length<=15}function params(form,p={}){return {form:form.id||p.source||'lead',page:location.pathname,service:p.service||'Консультация'}}function bind(form,build){let started=false,requestId=null,lastPayload='',busy=false,opened=false;const status=form.querySelector('.lead-status'),submit=form.querySelector('button[type="submit"]'),contact=form.querySelector('[name=contact]');function markOpen(){if(!opened){opened=true;goal('lead_open',params(form,build()))}}form.addEventListener('focusin',markOpen);form.addEventListener('input',e=>{if(e.target.name==='contact')contact.setCustomValidity('');if(!started&&['contact','details','amount'].includes(e.target.name)){started=true;goal('lead_start',params(form,build()))}});form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;contact.value=contact.value.trim();contact.setCustomValidity(validContact(contact.value)?'':'Укажите телефон с кодом страны или Telegram: @username');if(!form.reportValidity())return;markOpen();const data=new FormData(form),extra=build()||{},payload={...extra,contact:contact.value,consent:data.get('consent')==='on',consent_version:'2026-10-30',website:data.get('website')||'',attribution:window.SirokkoAnalytics?.attribution||{},page:location.pathname};const signature=JSON.stringify(payload);if(signature!==lastPayload||!requestId){requestId=uuid();lastPayload=signature}payload.request_id=requestId;busy=true;submit.disabled=true;const original=submit.innerHTML;submit.textContent='Отправляем…';status.className='lead-status ym-hide-content';status.textContent='';goal('lead_submit',params(form,payload));const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),35000);try{const response=await fetch(config.leadEndpoint||'/api/lead',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload),credentials:'same-origin',signal:controller.signal});let result;try{result=await response.json()}catch{throw new Error('Не удалось отправить заявку. Попробуйте ещё раз или напишите нам в Telegram / MAX.')}if(!response.ok||result.ok!==true||result.delivered!==true)throw new Error(result.message||'Не удалось подтвердить доставку заявки. Попробуйте позже или напишите нам.');status.classList.add('success');status.textContent='Заявка отправлена! Менеджер свяжется с вами по указанному контакту.';const key='sirokko_goal_'+requestId;let counted=false;try{counted=sessionStorage.getItem(key)==='1';sessionStorage.setItem(key,'1')}catch{}if(!counted){const p=params(form,payload);goal('lead_success',p);goal(payload.kind==='cargo'?'cargo_lead_success':'payment_lead_success',p)}submit.textContent='Заявка отправлена ✓';submit.disabled=true;form.dataset.delivered='true';}catch(error){status.classList.add('error');status.textContent=error.name==='AbortError'?'Не удалось подтвердить отправку. Попробуйте ещё раз или напишите менеджеру в Telegram / MAX.':error.message;goal('lead_error',{...params(form,payload),reason:error.name==='AbortError'?'timeout':'delivery'});submit.disabled=false;submit.innerHTML=original;}finally{clearTimeout(timer);busy=false}});form.addEventListener('input',()=>{if(form.dataset.delivered==='true'){delete form.dataset.delivered;submit.disabled=false;submit.innerHTML='Оставить заявку <span>↗</span>';status.textContent='';requestId=null}});return {markOpen,reset(){requestId=null;lastPayload='';started=false;opened=false;delete form.dataset.delivered;status.textContent='';submit.disabled=false;submit.innerHTML='Оставить заявку <span>↗</span>'}}}
const binding=bind(modal.querySelector('form'),()=>({...modalData,details:modal.querySelector('[name=details]').value,kind:modalData.kind||(/Карго|доставка/i.test(modalData.service)?'cargo':'payment')}));function open(data={}){modalData={service:'Консультация',source:'quick_form',context:'',...data};previousFocus=document.activeElement;binding.reset();modal.querySelector('#quick-lead-context').textContent=modalData.service+(modalData.context?' · Параметры расчёта уже добавлены':'');if(!modal.open)modal.showModal();binding.markOpen();setTimeout(()=>modal.querySelector('[name=contact]').focus(),0)}modal.querySelector('.quick-lead-close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{const r=modal.getBoundingClientRect();if(e.target===modal&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))modal.close()});modal.addEventListener('close',()=>previousFocus?.focus?.());document.addEventListener('click',e=>{const b=e.target.closest('[data-lead-open]');if(!b)return;e.preventDefault();open({service:b.dataset.leadService||b.dataset.service||(location.pathname.includes('cargo')?'Карго из Китая':'Консультация'),source:'cta',kind:location.pathname.includes('cargo')?'cargo':'payment'})});document.querySelectorAll('a[href]').forEach(a=>{try{const host=new URL(a.href).hostname;if(host==='t.me'&&config.telegram)a.href=config.telegram;if(host==='max.ru'&&config.max)a.href=config.max}catch{}});window.SirokkoLeads={open,bind,validContact};})();
